/// Checks if a given number is even.
pub fn is_even(n: u32) -> bool {
    n % 2 == 0
}

/// Executes the even check for a given number.
pub fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

/// Checks if there is at least one even number in the given array.
pub fn is_product_even(arr: &Vec<u32>) -> bool {
    for &num in arr {
        if is_even(num) {
            return true;
        }
    }
    false
}

// Example usage
